import React,{useEffect,useMemo,useRef,useState}from'react';
import{createRoot}from'react-dom/client';
import{Archive,ArrowLeft,ArrowRight,Bot,Briefcase,Building2,Check,CheckCircle2,ChevronDown,ChevronLeft,ChevronRight,Clock3,Code2,Database,Download,Eye,File,Image as ImageIcon,Inbox,Info,Layers3,LayoutDashboard,Loader2,LockKeyhole,LogIn,Mail,MailCheck,Menu,MoreHorizontal,Palette,Paperclip,Pencil,Plus,RefreshCw,Search,Send,Server,Settings,ShieldCheck,Sparkles,Star,Tag,Trash2,Users,X,Zap}from'lucide-react';
import{AnimatePresence,motion,useReducedMotion}from'motion/react';
import'./styles.css';

const folders=[['Inbox',Inbox],['Starred',Star],['Snoozed',Clock3],['Sent',Send],['Drafts',File],['Archive',Archive],['Trash',Trash2]];
const palette=['#657c86','#b79b79','#829175','#cf7258','#9a6e68'];
const defaultPrefs={theme:'light',density:'comfortable',notifications:true,refreshSeconds:30,signature:'Best,\nVedøy Studio',labels:['Campaign','Product','Retail','Press'],displayHtml:true,showAttachedImages:true,loadRemoteImages:false,markReadOnOpen:true};
const loadPrefs=()=>{try{return{...defaultPrefs,...JSON.parse(localStorage.getItem('vedoy.preferences')||'{}')}}catch{return defaultPrefs}};

function BrandLogo({compact=false}){return <div className={`vedoy-brand ${compact?'compact':''}`} aria-label="Vedøy Mailbox"><img className="logo-light" src="/brand/vedoy-logo-black.png" alt="Vedøy"/><img className="logo-dark" src="/brand/vedoy-logo-white.png" alt="Vedøy"/><span>MAILBOX</span></div>}
function LegalDock(){return <nav className="legal-dock" aria-label="Juridisk informasjon"><span>Juridisk:</span><a href="/privacy">Personvern</a><a href="/terms">Vilkår</a><a href="/cookies">Cookies</a><a href="/accessibility">Tilgjengelighet</a></nav>}

function App(){
 const[mail,setMail]=useState([]),[folder,setFolder]=useState('Inbox'),[selected,setSelected]=useState(null),[query,setQuery]=useState('');
 const[compose,setCompose]=useState(null),[connect,setConnect]=useState(false),[live,setLive]=useState(false),[configured,setConfigured]=useState(false),[entered,setEntered]=useState(()=>localStorage.getItem('vedoy.session')==='active');
 const[notice,setNotice]=useState(''),[mobileList,setMobileList]=useState(true),[mobileNav,setMobileNav]=useState(false),[workspace,setWorkspace]=useState(false),[settings,setSettings]=useState(false),[infoOpen,setInfoOpen]=useState(false),[accountMenu,setAccountMenu]=useState(false);
 const[aiAssist,setAiAssist]=useState(false),[businessAccess,setBusinessAccess]=useState(null),[loading,setLoading]=useState(false),[folderError,setFolderError]=useState(''),[lastUpdated,setLastUpdated]=useState(null);
 const[listMenu,setListMenu]=useState(false),[readerMenu,setReaderMenu]=useState(false),[labelMenu,setLabelMenu]=useState(false),[checked,setChecked]=useState([]),[prefs,setPrefs]=useState(loadPrefs),[messageLoading,setMessageLoading]=useState(false),[messageError,setMessageError]=useState('');
 const[accounts,setAccounts]=useState([]),[activeAccountId,setActiveAccountId]=useState(null),[seenPending,setSeenPending]=useState([]),[viewFilter,setViewFilter]=useState('all'),[replyLater,setReplyLater]=useState(()=>{try{return JSON.parse(localStorage.getItem('vedoy.reply-later')||'[]')}catch{return[]}});
 const cacheRef=useRef({}),requestRef=useRef(0),loadControllerRef=useRef(null),navigationTimerRef=useRef(null),detailRequestRef=useRef(0),folderRef=useRef(folder),selectedRef=useRef(selected),searchRef=useRef(null);
 const reduceMotion=useReducedMotion();
 const flash=x=>{setNotice(x);window.clearTimeout(window.__vedoyToast);window.__vedoyToast=window.setTimeout(()=>setNotice(''),2200)};
 const refreshAccounts=async()=>{const r=await fetch('/api/accounts',{cache:'no-store'});if(!r.ok)return;const data=await r.json();setAccounts(data.accounts||[]);setActiveAccountId(data.activeId||data.accounts?.[0]?.id||null)};
 const load=async(nextFolder=folderRef.current,{quiet=false}={})=>{loadControllerRef.current?.abort();const controller=new AbortController();loadControllerRef.current=controller;const request=++requestRef.current;if(!quiet)setLoading(true);setFolderError('');try{const r=await fetch(`/api/messages?folder=${encodeURIComponent(nextFolder)}`,{cache:'no-store',signal:controller.signal});const x=await r.json().catch(()=>({}));const missingProviderFolder=r.status===404&&/finnes ikke hos e-postleverandøren|folder.+not found/i.test(x.error||'');if(!r.ok&&!missingProviderFolder)throw Error(x.error||'Kunne ikke kontakte e-postserveren.');if(request!==requestRef.current||nextFolder!==folderRef.current)return;const existing=cacheRef.current[nextFolder]||[];const messages=(missingProviderFolder?[]:(x.messages||[])).map(summary=>({...existing.find(message=>message.id===summary.id),...summary}));cacheRef.current[nextFolder]=messages;setMail(messages);setChecked([]);setSelected(previous=>previous&&messages.some(message=>message.id===previous)?previous:null);setLive(true);setLastUpdated(new Date())}catch(e){if(e.name==='AbortError')return;if(request===requestRef.current&&nextFolder===folderRef.current){setFolderError(e.message);if(!cacheRef.current[nextFolder])setMail([]);if(!quiet)flash(`${e.message} Eksisterende e-poster er beholdt.`)}}finally{if(request===requestRef.current){setLoading(false);if(loadControllerRef.current===controller)loadControllerRef.current=null}}};
 useEffect(()=>{folderRef.current=folder},[folder]);
 useEffect(()=>()=>{loadControllerRef.current?.abort();window.clearTimeout(navigationTimerRef.current)},[]);
 useEffect(()=>{selectedRef.current=selected},[selected]);
 useEffect(()=>{Promise.all([fetch('/api/health').then(r=>r.json()),fetch('/api/accounts').then(r=>r.json())]).then(([health,accountData])=>{setConfigured(!!health.configured);setAccounts(accountData.accounts||[]);setActiveAccountId(accountData.activeId||accountData.accounts?.[0]?.id||null);if(health.configured&&localStorage.getItem('vedoy.session')==='active')restore()}).catch(()=>{})},[]);
 useEffect(()=>{const apply=()=>{const resolved=prefs.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):prefs.theme;document.documentElement.dataset.theme=resolved;document.documentElement.dataset.density=prefs.density};apply();const media=matchMedia('(prefers-color-scheme: dark)');media.addEventListener?.('change',apply);localStorage.setItem('vedoy.preferences',JSON.stringify(prefs));return()=>media.removeEventListener?.('change',apply)},[prefs]);
 useEffect(()=>{if(!live||!entered)return;const seconds=Math.max(15,Number(prefs.refreshSeconds)||30);const refresh=()=>{if(document.visibilityState==='visible'&&navigator.onLine)load(folderRef.current,{quiet:true})};const timer=window.setInterval(refresh,seconds*1000);window.addEventListener('focus',refresh);window.addEventListener('online',refresh);return()=>{clearInterval(timer);window.removeEventListener('focus',refresh);window.removeEventListener('online',refresh)}},[live,entered,prefs.refreshSeconds]);
 useEffect(()=>localStorage.setItem('vedoy.reply-later',JSON.stringify(replyLater)),[replyLater]);
 const laterKey=m=>`${activeAccountId||'mail'}:${folder}:${m.id}`;
 const filtered=useMemo(()=>mail.filter(m=>folder==='Starred'?m.starred:folder==='Snoozed'?false:true).filter(m=>viewFilter==='unread'?m.unread:viewFilter==='later'?replyLater.includes(`${activeAccountId||'mail'}:${folder}:${m.id}`):true).filter(m=>(m.from+m.subject+m.preview).toLowerCase().includes(query.toLowerCase())),[mail,folder,query,viewFilter,replyLater,activeAccountId]);
 const current=mail.find(x=>x.id===selected);
 const activeAccount=accounts.find(x=>x.id===activeAccountId)||accounts[0];
 const choose=async m=>{const activeFolder=folderRef.current,request=++detailRequestRef.current,wasUnread=m.unread;selectedRef.current=m.id;setSelected(m.id);setMobileList(false);setMessageError('');setMessageLoading(true);if(prefs.markReadOnOpen)setMail(x=>{const updated=x.map(y=>y.id===m.id?{...y,unread:false}:y);cacheRef.current[activeFolder]=updated;return updated});if(!live){setMessageLoading(false);return}try{const r=await fetch(`/api/messages/${m.id}?folder=${encodeURIComponent(activeFolder)}&markSeen=${prefs.markReadOnOpen?'true':'false'}`,{cache:'no-store'});const full=await r.json().catch(()=>({}));if(!r.ok)throw Error(full.error||'Kunne ikke åpne meldingen.');if(request!==detailRequestRef.current||folderRef.current!==activeFolder||selectedRef.current!==m.id)return;setMail(x=>{const updated=x.map(y=>y.id===m.id?{...y,...full}:y);cacheRef.current[activeFolder]=updated;return updated})}catch(e){if(request===detailRequestRef.current){setMessageError(e.message);if(prefs.markReadOnOpen&&wasUnread)setMail(x=>{const updated=x.map(y=>y.id===m.id?{...y,unread:true}:y);cacheRef.current[activeFolder]=updated;return updated})}}finally{if(request===detailRequestRef.current)setMessageLoading(false)}};
 const star=async m=>{setMail(x=>x.map(y=>y.id===m.id?{...y,starred:!y.starred}:y));if(live)await fetch(`/api/messages/${m.id}/star`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder,starred:!m.starred})})};
 const move=async(destination,item=current)=>{if(!item)return;setMail(x=>x.filter(y=>y.id!==item.id));setSelected(null);if(live)await fetch(`/api/messages/${item.id}/move`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder,destination})});flash(destination==='Archive'?'Conversation archived':'Moved to trash')};
 const markSeen=async(item=current,seen=true)=>{if(!item||seenPending.includes(item.id))return;const activeFolder=folderRef.current,previousUnread=item.unread;setSeenPending(x=>[...x,item.id]);setMail(x=>{const updated=x.map(y=>y.id===item.id?{...y,unread:!seen}:y);cacheRef.current[activeFolder]=updated;return updated});try{if(live){const r=await fetch(`/api/messages/${item.id}/seen`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder:activeFolder,seen})});if(!r.ok){const data=await r.json().catch(()=>({}));throw Error(data.error||'Kunne ikke oppdatere lest-status.')}}flash(seen?'Markert som lest':'Markert som ulest')}catch(e){setMail(x=>{const updated=x.map(y=>y.id===item.id?{...y,unread:previousUnread}:y);cacheRef.current[activeFolder]=updated;return updated});flash(e.message)}finally{setSeenPending(x=>x.filter(id=>id!==item.id))}};
 const toggleReplyLater=(item=current)=>{if(!item)return;const key=laterKey(item),isSaved=replyLater.includes(key);setReplyLater(x=>isSaved?x.filter(id=>id!==key):[...x,key]);flash(isSaved?'Fjernet fra Svar senere':'Lagt til i Svar senere')};
 const addLabel=label=>{if(!current)return;setMail(x=>x.map(y=>y.id===current.id?{...y,labels:[...new Set([...(y.labels||[]),label])]}:y));setLabelMenu(false);flash(`Added ${label} label`)};
 const toggleAll=()=>setChecked(checked.length===filtered.length?[]:filtered.map(x=>x.id));
 const bulkMove=async destination=>{for(const id of checked){const item=mail.find(x=>x.id===id);if(item)await move(destination,item)}setChecked([])};
 const changeFolder=n=>{if(n===folderRef.current&&!folderError)return;window.clearTimeout(window.__vedoyToast);window.clearTimeout(navigationTimerRef.current);setNotice('');folderRef.current=n;detailRequestRef.current++;setFolder(n);selectedRef.current=null;setSelected(null);setMobileList(true);setMobileNav(false);setMessageError('');setMessageLoading(false);setFolderError('');const cached=cacheRef.current[n];setMail(cached||[]);setChecked([]);setLoading(live&&!cached);if(live)navigationTimerRef.current=window.setTimeout(()=>load(n,{quiet:!!cached}),180)};
 const openCompose=mode=>{if(!live)return setConnect(true);if(mode==='reply'&&current)setCompose({to:current.email,subject:`Re: ${current.subject.replace(/^Re:\s*/i,'')}`,text:''});else if(mode==='forward'&&current)setCompose({to:'',subject:`Fwd: ${current.subject.replace(/^Fwd:\s*/i,'')}`,text:`\n\n---------- Forwarded message ----------\nFrom: ${current.from} <${current.email}>\nSubject: ${current.subject}\n\n${current.body||current.preview}`});else setCompose({to:'',subject:'',text:''})};
 const logout=async()=>{await fetch('/api/auth/logout',{method:'POST'});localStorage.removeItem('vedoy.session');setEntered(false);setLive(false);setMail([]);cacheRef.current={};setAccountMenu(false);flash('Signed out')};
 const forget=async()=>{const r=await fetch('/api/auth/forget',{method:'DELETE'});if(r.ok){localStorage.removeItem('vedoy.session');setConfigured(false);setEntered(false);setLive(false);setMail([]);cacheRef.current={};setSettings(false)}};
 const restore=async()=>{const r=await fetch('/api/auth/restore',{method:'POST'});if(r.ok){localStorage.setItem('vedoy.session','active');setEntered(true);setLive(true);folderRef.current='Inbox';setFolder('Inbox');await refreshAccounts();setTimeout(()=>load('Inbox'),0)}else{localStorage.removeItem('vedoy.session');setEntered(false);setConnect(true)}};
 const switchAccount=async id=>{if(id===activeAccountId)return setAccountMenu(false);setLoading(true);try{const r=await fetch(`/api/accounts/${id}/activate`,{method:'POST'});if(!r.ok)throw Error('Kunne ikke bytte konto.');setActiveAccountId(id);cacheRef.current={};folderRef.current='Inbox';setFolder('Inbox');setSelected(null);setMail([]);setAccountMenu(false);await load('Inbox');flash('E-postkonto byttet')}catch(e){flash(e.message)}finally{setLoading(false)}};
 const removeAccount=async id=>{const r=await fetch(`/api/accounts/${id}`,{method:'DELETE'});const data=await r.json().catch(()=>({}));if(!r.ok)return flash(data.error||'Kunne ikke fjerne kontoen.');setAccounts(data.accounts||[]);setActiveAccountId(data.activeId||null);cacheRef.current={};setSelected(null);if(data.activeId){setLive(true);await load('Inbox')}else{setLive(false);setConfigured(false);setMail([])}flash('E-postkonto fjernet')};
 const afterConnected=async data=>{localStorage.setItem('vedoy.session','active');setConnect(false);setEntered(true);setConfigured(true);setLive(true);setAccounts(data?.accounts||accounts);setActiveAccountId(data?.activeId||data?.id||activeAccountId);cacheRef.current={};folderRef.current='Inbox';setFolder('Inbox');setSelected(null);setTimeout(()=>load('Inbox'),0);flash('E-postkontoen er tilkoblet')};
 useEffect(()=>{if(!entered)return;const onKey=e=>{const tag=e.target?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag)||e.target?.isContentEditable)return;if(e.key==='/'){e.preventDefault();searchRef.current?.focus()}else if(e.key.toLowerCase()==='c'){e.preventDefault();openCompose()}else if(e.key.toLowerCase()==='r'&&current){e.preventDefault();openCompose('reply')}else if(e.key.toLowerCase()==='u'&&current){e.preventDefault();markSeen(current,current.unread)}else if((e.key.toLowerCase()==='j'||e.key.toLowerCase()==='k')&&filtered.length){e.preventDefault();const index=Math.max(0,filtered.findIndex(x=>x.id===current?.id)),next=e.key.toLowerCase()==='j'?Math.min(filtered.length-1,index+1):Math.max(0,index-1);choose(filtered[next])}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[entered,current,filtered,live]);
 return <div className={`app ${mobileNav?'mobile-nav-open':''}`} data-loading={loading?'true':'false'} onClick={()=>{setListMenu(false);setReaderMenu(false);setLabelMenu(false)}}>
  <header><button className="icon mobile" aria-label="Åpne navigasjon" onClick={e=>{e.stopPropagation();setMobileNav(x=>!x)}}><Menu/></button><BrandLogo compact/><div className="search"><Search/><input ref={searchRef} value={query} onChange={e=>setQuery(e.target.value)} placeholder="Søk i e-post"/>{query?<button aria-label="Tøm søk" onClick={()=>setQuery('')}><X/></button>:<kbd>/</kbd>}</div><div className="head-actions"><button className="connect-btn workspace-button" onClick={()=>setWorkspace(true)}><LayoutDashboard/> <span>Workspace</span></button><button className="connect-btn account-button" onClick={()=>live?setAccountMenu(x=>!x):setConnect(true)}><span>{activeAccount?.email||'Koble til e-post'}</span><ChevronDown/></button><button className="icon" aria-label="Om og funksjoner" title="Om og funksjoner" onClick={()=>setInfoOpen(true)}><Info/></button><button className="icon" aria-label="Innstillinger" onClick={()=>setSettings(true)}><Settings/></button><button className="avatar main" onClick={()=>setAccountMenu(x=>!x)}>{activeAccount?.label?.slice(0,2).toUpperCase()||'VS'}</button><AnimatePresence>{accountMenu&&<motion.div initial={{opacity:0,y:-8,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:-6,scale:.98}} transition={{duration:reduceMotion?0:.16}} className="popover account-pop account-switcher" onClick={e=>e.stopPropagation()}><div className="account-pop-head"><b>E-postkontoer</b><small>{accounts.length} av 5 tilkoblet</small></div><div className="account-list">{accounts.map(account=><button key={account.id} className={account.id===activeAccountId?'active':''} onClick={()=>switchAccount(account.id)}><span className="account-dot">{account.label?.slice(0,2).toUpperCase()}</span><span><b>{account.label}</b><small>{account.email}</small></span>{account.id===activeAccountId?<CheckCircle2/>:<ChevronRight/>}</button>)}</div><button className="account-add" onClick={()=>{setConnect(true);setAccountMenu(false)}}><Plus/> Legg til e-postkonto</button><button onClick={()=>{setSettings(true);setAccountMenu(false)}}>Administrer kontoer</button><button onClick={logout}>Logg ut</button></motion.div>}</AnimatePresence></div></header>
  <aside><button className="compose" onClick={()=>openCompose()}><Pencil/>Compose</button><nav>{folders.map(([n,I])=><button key={n} className={folder===n?'active':''} onClick={()=>changeFolder(n)}><I/><span>{n}</span>{n==='Inbox'&&mail.some(x=>x.unread)&&<b>{mail.filter(x=>x.unread).length}</b>}</button>)}</nav><div className="labels"><h5>LABELS <button aria-label="Manage labels" onClick={()=>setSettings(true)}>+</button></h5>{prefs.labels.map((x,i)=><button key={x} onClick={()=>setQuery(query===x?'':x)}><i style={{background:palette[i%palette.length]}}/>{x}</button>)}</div><div className="storage"><div><span>{live?'Live IMAP':'Mailbox disconnected'}</span><b>{live?'Connected':'Connect to send mail'}</b></div><progress value={live?15:0} max="15"/></div></aside>
  <main className={mobileList?'show-list':'show-reader'}><section className="list"><div className="list-head"><div><h1>{folder}</h1><span>{filtered.length} samtaler · {mail.filter(x=>x.unread).length} ulest</span></div><button className="icon" aria-label={`Oppdater ${folder}`} disabled={loading} onClick={()=>live?load(folderRef.current):setConnect(true)}>{loading?<Loader2/>:<RefreshCw/>}</button></div><div className="smart-filters" role="tablist" aria-label="Filtrer e-post"><button role="tab" aria-selected={viewFilter==='all'} className={viewFilter==='all'?'active':''} onClick={()=>setViewFilter('all')}>Alle</button><button role="tab" aria-selected={viewFilter==='unread'} className={viewFilter==='unread'?'active':''} onClick={()=>setViewFilter('unread')}>Ulest <span>{mail.filter(x=>x.unread).length}</span></button><button role="tab" aria-selected={viewFilter==='later'} className={viewFilter==='later'?'active':''} onClick={()=>setViewFilter('later')}>Svar senere <span>{mail.filter(m=>replyLater.includes(laterKey(m))).length}</span></button></div><div className="list-tools"><label title="Velg alle"><input type="checkbox" checked={!!filtered.length&&checked.length===filtered.length} onChange={toggleAll}/><ChevronDown/></label>{checked.length?<div className="bulk"><span>{checked.length} valgt</span><button onClick={()=>bulkMove('Archive')}><Archive/></button><button onClick={()=>bulkMove('Trash')}><Trash2/></button></div>:<span/>}<small>{filtered.length?`1–${filtered.length} av ${filtered.length}`:'0 meldinger'}</small><div className="menu-wrap"><button className="icon" aria-label="Listevalg" onClick={e=>{e.stopPropagation();setListMenu(x=>!x)}}><MoreHorizontal/></button>{listMenu&&<div className="popover list-pop" onClick={e=>e.stopPropagation()}><button onClick={()=>setPrefs(x=>({...x,density:x.density==='compact'?'comfortable':'compact'}))}>Bytt kompakt visning</button><button onClick={()=>{setQuery('');setViewFilter('all')}}>Fjern filtre</button><button onClick={()=>live&&load(folderRef.current)}>Oppdater nå</button></div>}</div></div><div className="messages">{loading&&!mail.length?<div className="list-loading" role="status"><motion.div animate={{rotate:360}} transition={{duration:.8,repeat:Infinity,ease:'linear'}}><Loader2/></motion.div><b>Henter e-postene dine</b><span>Kobler sikkert til IMAP…</span></div>:folderError&&!mail.length?<div className="list-error" role="alert"><Mail/><b>Kunne ikke laste {folder}</b><span>{folderError}</span><button onClick={()=>load(folderRef.current)}><RefreshCw/> Prøv igjen</button></div>:filtered.length?<AnimatePresence initial={false}>{filtered.map((m,index)=><motion.article layout={!reduceMotion} initial={reduceMotion?false:{opacity:0,y:8}} animate={{opacity:1,y:0}} exit={{opacity:0,x:-18}} transition={{duration:reduceMotion?0:.18,delay:reduceMotion?0:Math.min(index,7)*.018}} key={m.id} className={`${m.id===selected?'selected':''} ${m.unread?'unread':'read'}`} onClick={()=>choose(m)}><input className="row-check" type="checkbox" checked={checked.includes(m.id)} onClick={e=>e.stopPropagation()} onChange={()=>setChecked(x=>x.includes(m.id)?x.filter(id=>id!==m.id):[...x,m.id])}/><button className="star" aria-label="Stjernemerk melding" onClick={e=>{e.stopPropagation();star(m)}}><Star fill={m.starred?'currentColor':'none'}/></button><div className="avatar" style={{background:m.color}}>{m.avatar}</div><div className="mailcopy"><div><strong>{m.from}</strong><span className={`read-indicator ${m.unread?'new':''}`}>{m.unread?'NY':'LEST'}</span><time>{m.time}</time></div><h3>{m.subject}</h3><p>{m.preview}</p><div className="chips">{replyLater.includes(laterKey(m))?<span className="later-chip"><Clock3/> Svar senere</span>:null}{m.labels?.map(x=><span key={x}>{x}</span>)}</div></div></motion.article>)}</AnimatePresence>:<div className="empty"><Mail/><h3>{live?'Ingen meldinger i denne visningen':'Koble til e-postkontoen din'}</h3><p>{live?'Prøv et annet filter eller oppdater innboksen.':'Koble til en ekte IMAP-konto for å lese og sende e-post.'}</p>{!live?<button onClick={()=>setConnect(true)}>Koble til e-post</button>:viewFilter!=='all'?<button onClick={()=>setViewFilter('all')}>Vis alle meldinger</button>:null}</div>}</div></section>
  <section className="reader">{current?<><div className="reader-tools"><button className="icon back" aria-label="Tilbake til listen" onClick={()=>setMobileList(true)}><ArrowLeft/></button><button className="icon" aria-label="Arkiver" onClick={()=>move('Archive')}><Archive/></button><button className={`icon ${replyLater.includes(laterKey(current))?'active':''}`} aria-label="Svar senere" title="Svar senere" onClick={()=>toggleReplyLater(current)}><Clock3/></button><div className="menu-wrap"><button className="icon" aria-label="Legg til etikett" onClick={e=>{e.stopPropagation();setLabelMenu(x=>!x)}}><Tag/></button>{labelMenu&&<div className="popover label-pop" onClick={e=>e.stopPropagation()}>{prefs.labels.map(x=><button key={x} onClick={()=>addLabel(x)}>{x}</button>)}</div>}</div><button className="icon" aria-label="Slett" onClick={()=>move('Trash')}><Trash2/></button><span/><button className="icon" aria-label="Forrige melding" onClick={()=>{const i=filtered.findIndex(x=>x.id===current.id);if(i>0)choose(filtered[i-1])}}><ChevronLeft/></button><button className="icon" aria-label="Neste melding" onClick={()=>{const i=filtered.findIndex(x=>x.id===current.id);if(i<filtered.length-1)choose(filtered[i+1])}}><ChevronRight/></button><div className="menu-wrap"><button className="icon" aria-label="Meldingsvalg" onClick={e=>{e.stopPropagation();setReaderMenu(x=>!x)}}><MoreHorizontal/></button>{readerMenu&&<div className="popover reader-pop" onClick={e=>e.stopPropagation()}><button disabled={seenPending.includes(current.id)} onClick={()=>markSeen(current,current.unread)}>{current.unread?'Marker som lest':'Marker som ulest'}</button><button onClick={()=>toggleReplyLater(current)}>{replyLater.includes(laterKey(current))?'Fjern fra Svar senere':'Legg til i Svar senere'}</button><button onClick={()=>star(current)}>{current.starred?'Fjern stjerne':'Legg til stjerne'}</button><button onClick={()=>navigator.clipboard?.writeText(current.email).then(()=>flash('Avsenderadressen er kopiert'))}>Kopier avsenderadresse</button><button onClick={()=>window.print()}>Skriv ut melding</button></div>}</div></div><motion.div key={current.id} initial={reduceMotion?false:{opacity:0,y:10}} animate={{opacity:1,y:0}} transition={{duration:reduceMotion?0:.22}} className="letter"><div className="subject-row"><div><div className="eyebrow">{current.labels?.[0]||'E-post'} · {current.unread?'ULEST':'LEST'}</div><h2>{current.subject}</h2></div><button className="star big" aria-label="Stjernemerk melding" onClick={()=>star(current)}><Star fill={current.starred?'currentColor':'none'}/></button></div><div className="sender"><div className="avatar" style={{background:current.color}}>{current.avatar}</div><div><b>{current.from}</b><p>{current.email}</p></div><time>{current.date}</time></div><MessageContent message={current} folder={folder} prefs={prefs} loading={messageLoading} error={messageError} onRetry={()=>choose(current)}/><div className="reply"><button onClick={()=>openCompose('reply')}><ArrowLeft/> Svar</button><button onClick={()=>openCompose('forward')}><Users/> Videresend</button></div></motion.div></>:<div className="empty"><Mail/><h3>Velg en samtale</h3><p>Bruk J og K for å navigere raskt.</p></div>}</section></main>
  {!entered&&<Landing configured={configured} onOpen={restore} onConnect={()=>setConnect(true)} onBusiness={mode=>setBusinessAccess(mode)} onInfo={()=>setInfoOpen(true)}/>} 
  {workspace&&<Workspace unread={mail.filter(x=>x.unread).length} onClose={()=>setWorkspace(false)} onCompose={()=>{setWorkspace(false);openCompose()}}/>}
  {compose&&<Compose live={live} accountId={activeAccountId} initial={compose} signature={prefs.signature} onClose={()=>setCompose(null)} onSent={()=>{setCompose(null);flash('E-posten er sendt')}}/>}
  {connect&&<Connect onClose={()=>setConnect(false)} onConnected={afterConnected}/>}
  {settings&&<SettingsModalV2 prefs={prefs} setPrefs={setPrefs} live={live} accounts={accounts} activeAccountId={activeAccountId} onSwitch={switchAccount} onRemove={removeAccount} onClose={()=>setSettings(false)} onReconnect={()=>{setSettings(false);setConnect(true)}} onForget={forget}/>} 
  {businessAccess&&<BusinessAccess initialMode={businessAccess} configured={configured} onClose={()=>setBusinessAccess(null)} onLogin={()=>{setBusinessAccess(null);configured?restore():setConnect(true)}} onBecomeCustomer={()=>{setBusinessAccess(null);setConnect(true);flash('Bedriftsprofilen er lagret. Koble til første e-postkonto.')}}/>}
  {infoOpen&&<InfoPage onClose={()=>setInfoOpen(false)}/>} 
  <AnimatePresence>{loading&&mail.length>0?<motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-8}} className="mail-loading" role="status"><Loader2/><span>Henter e-post…</span></motion.div>:null}</AnimatePresence>
  <AnimatePresence>{notice?<motion.div initial={{opacity:0,y:12,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:8}} className="toast" role="status" aria-live="polite">{notice}</motion.div>:null}</AnimatePresence>
  {current&&entered&&!compose&&<button className={`read-toolbar-action ${current.unread?'unread':'read'}`} disabled={seenPending.includes(current.id)} title={current.unread?'Marker som lest':'Marker som ulest'} onClick={()=>markSeen(current,current.unread)}>{seenPending.includes(current.id)?<Loader2/>:current.unread?<MailCheck/>:<CheckCircle2/>}<span>{seenPending.includes(current.id)?'Lagrer…':current.unread?'Marker som lest':'Lest · marker ulest'}</span></button>}
  {current&&entered&&!compose&&<button className="ai-fab" onClick={()=>setAiAssist(true)}><Sparkles/> Hjelp meg å svare</button>}
  {aiAssist&&current&&<AiReply message={current} onClose={()=>setAiAssist(false)} onDraft={draft=>{setCompose({to:current.email,subject:`Re: ${current.subject.replace(/^Re:\s*/i,'')}`,text:draft});setAiAssist(false)}}/>}
 </div>
}

function Compose({live,accountId,initial,signature,onClose,onSent}){const draftKey=`vedoy.draft.${accountId||'mail'}`,draft=useMemo(()=>{try{return JSON.parse(localStorage.getItem(draftKey)||'null')}catch{return null}},[draftKey]);const[to,setTo]=useState(initial.to||draft?.to||''),[subject,setSubject]=useState(initial.subject||draft?.subject||''),[text,setText]=useState(initial.text||draft?.text||''),[files,setFiles]=useState([]),[error,setError]=useState(''),[sending,setSending]=useState(false),[savedAt,setSavedAt]=useState(null);const fileRef=useRef();useEffect(()=>{const timer=window.setTimeout(()=>{if(to||subject||text){localStorage.setItem(draftKey,JSON.stringify({to,subject,text,updatedAt:Date.now()}));setSavedAt(new Date())}},500);return()=>clearTimeout(timer)},[draftKey,to,subject,text]);const addFiles=async list=>{const items=[];for(const file of [...list].slice(0,3)){if(file.size>5*1024*1024){setError(`${file.name} er større enn 5 MB`);continue}const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));items.push({filename:file.name,contentType:file.type||'application/octet-stream',content:btoa(binary)})}setFiles(x=>[...x,...items].slice(0,3))};const send=async()=>{if(!live)return setError('Koble til en e-postkonto før du sender.');setSending(true);setError('');try{const fullText=`${text}${signature?`\n\n${signature}`:''}`;const r=await fetch('/api/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({to,subject,text:fullText,attachments:files})});if(!r.ok){const x=await r.json();return setError(x.error||'E-posten kunne ikke sendes.')}localStorage.removeItem(draftKey);onSent()}finally{setSending(false)}};const discard=()=>{if((to||subject||text)&&!window.confirm('Vil du forkaste dette utkastet?'))return;localStorage.removeItem(draftKey);onClose()};return <motion.div initial={{opacity:0,y:24,scale:.985}} animate={{opacity:1,y:0,scale:1}} transition={{type:'spring',stiffness:380,damping:32}} className="compose-panel"><div className="compose-head"><b>Ny e-post</b><span className="draft-status"><Check/> {savedAt?'Utkast lagret':'Lagrer automatisk'}</span><button className="icon" onClick={onClose}><X/></button></div><label>Til <input value={to} onChange={e=>setTo(e.target.value)} autoFocus/></label><input className="subject" placeholder="Emne" value={subject} onChange={e=>setSubject(e.target.value)}/><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Skriv en melding…"/>{files.length>0&&<div className="file-list">{files.map((f,i)=><span key={i}>{f.filename}<button onClick={()=>setFiles(x=>x.filter((_,n)=>n!==i))}><X/></button></span>)}</div>}{error&&<small className="error compose-error">{error}</small>}<div className="compose-foot"><button className="send" disabled={!to||!subject||!text||!live||sending} onClick={send}>{sending?'Sender…':'Send'} <Send/></button><input ref={fileRef} hidden type="file" multiple onChange={e=>addFiles(e.target.files)}/><button className="icon" aria-label="Legg ved filer" onClick={()=>fileRef.current?.click()}><Paperclip/></button><span/><button className="icon" aria-label="Forkast utkast" onClick={discard}><Trash2/></button></div></motion.div>}

function InfoPage({onClose}){const features=[
 {icon:<Mail/>,title:'Flere ekte e-postkontoer',text:'Koble til opptil fem jobb- og privatkontoer med IMAP og SMTP, og bytt konto uten å logge ut.'},
 {icon:<RefreshCw/>,title:'Smart oppdatering',text:'Automatisk sjekk når fanen er aktiv, manuelt refresh og et intervall som lagres lokalt.'},
 {icon:<MailCheck/>,title:'En tydelig arbeidskø',text:'Skill mellom lest og ulest, filtrer på nye meldinger og legg viktige samtaler i Svar senere.'},
 {icon:<Paperclip/>,title:'Skriv uten å miste arbeid',text:'Utkast lagres automatisk lokalt. Svar, videresend, bruk signatur og legg ved opptil tre filer.'},
 {icon:<Sparkles/>,title:'KI-hjelp til svar',text:'Lag et redigerbart svarutkast med ønsket tone. Ingenting sendes automatisk.'},
 {icon:<Layers3/>,title:'Personlig arbeidsflate',text:'Flytt, legg til og fjern moduler i Workspace. Notater og oppsett huskes på enheten.'},
 {icon:<Palette/>,title:'Rask og behagelig',text:'Velg tema og tetthet, bruk tastatursnarveier og få rolige Motion-animasjoner som respekterer redusert bevegelse.'},
 {icon:<ShieldCheck/>,title:'Sikker håndtering',text:'E-postpassord lagres ikke i localStorage. Oppsettet håndteres kryptert på serversiden.'}
  ];return <div className="info-page"><header className="info-header"><BrandLogo/><button className="info-close" onClick={onClose}><ArrowLeft/> Tilbake til innboksen</button></header><main className="info-main"><section className="info-hero"><div><span>OM VEDØY MAILBOX</span><h1>Alt appen kan gjøre.</h1><p>En oversikt for deg som bare vil bruke e-post – og detaljer for deg som vil vite hvordan alt fungerer under panseret.</p></div><div className="info-orbit" aria-hidden="true"><Mail/><span>IMAP</span><span>SMTP</span><span>KI</span></div></section><section className="info-features"><div className="info-section-title"><span>FUNKSJONER</span><h2>Bygget for daglig bruk</h2></div><div className="info-feature-grid">{features.map(feature=><article key={feature.title}><div>{feature.icon}</div><h3>{feature.title}</h3><p>{feature.text}</p></article>)}</div></section><section className="nerd-section"><div className="info-section-title"><span>FOR NERDER</span><h2>Teknikken bak</h2><p>Åpne et tema for flere detaljer.</p></div><div className="tech-accordions"><details><summary><span><Code2/> Frontend og grensesnitt</span><ChevronDown/></summary><div><p><b>Rammeverk:</b> React med funksjonelle komponenter og hooks.</p><p><b>Byggverktøy:</b> Vite, som lager en rask statisk klient og optimaliserte produksjonsfiler.</p><p><b>Bevegelse:</b> Motion for React gir korte, GPU-vennlige overganger. Systemvalget for redusert bevegelse blir respektert.</p><p><b>Ikoner:</b> Lucide React og et eget responsivt Vedøy-designsystem.</p></div></details><details><summary><span><Server/> Backend og e-post</span><ChevronDown/></summary><div><p><b>API:</b> Express-ruter for tilkobling, kontoer, mapper, meldinger, handlinger og sending.</p><p><b>Innkommende e-post:</b> ImapFlow kobler til leverandørens IMAP-server. Mailparser leser MIME, ren tekst, HTML og vedlegg.</p><p><b>Utgående e-post:</b> Nodemailer sender gjennom den aktive kontoens SMTP-server.</p></div></details><details><summary><span><Database/> Lagring og sikkerhet</span><ChevronDown/></summary><div><p><b>Server:</b> Hver konto forsegles separat med AES-256-GCM. Produksjonscookies er HttpOnly, Secure og SameSite=Lax.</p><p><b>Nettleser:</b> localStorage brukes til ufølsomme valg og lokale utkast – aldri e-postpassordet.</p><p><b>Viktig:</b> Vanlig IMAP/SMTP er ikke ende-til-ende-kryptert som Signal. Transportkryptering avhenger av TLS hos e-postleverandøren.</p></div></details><details><summary><span><Bot/> KI og personvern</span><ChevronDown/></summary><div><p><b>Modelltilkobling:</b> OpenAI-kallet skjer på serveren, og API-nøkkelen holdes borte fra klientkoden.</p><p><b>Kontroll:</b> Innhold sendes til KI først når brukeren ber om et utkast. Resultatet kan redigeres og blir aldri sendt automatisk.</p></div></details><details><summary><span><Layers3/> Produksjon og drift</span><ChevronDown/></summary><div><p><b>Hosting:</b> Vercel leverer React-klienten og kjører Express-adapteren som serverless API.</p><p><b>Integrasjon:</b> Appen kan brukes med Domeneshop og andre leverandører som tilbyr standard IMAP og SMTP.</p></div></details></div></section></main><footer className="info-footer"><BrandLogo compact/><p>Vedøy Mailbox · profesjonell e-post uten unødvendig støy.</p><button onClick={onClose}>Åpne innboksen <ArrowRight/></button></footer></div>}

function Landing({configured,onOpen,onConnect,onBusiness,onInfo}){return <div className="landing">
 <nav className="landing-nav"><BrandLogo/><div><button className="nav-info" aria-label="Om og funksjoner" title="Om og funksjoner" onClick={onInfo}><Info/></button><button className="nav-login" onClick={()=>onBusiness('login')}><LogIn/> Bedriftsinnlogging</button><button className="nav-primary" onClick={configured?onOpen:onConnect}>{configured?'Åpne innboksen':'Sett opp e-post'}</button></div></nav>
 <main className="landing-main">
  <section className="landing-hero"><div className="hero-copy"><div className="landing-kicker"><span/> E-POST FOR BEDRIFTER OG DEG</div><h1>En roligere måte<br/>å håndtere e-post.</h1><p>Samle jobb og privat på ett sted. Vedøy Mailbox kobler seg til e-posten du allerede har – med et ryddig grensesnitt, rask oppdatering og trygg lagring.</p><div className="hero-actions"><button className="landing-cta" onClick={configured?onOpen:onConnect}>{configured?'Gå til innboksen':'Koble til e-post'} <ArrowRight/></button><button className="landing-secondary" onClick={()=>onBusiness('customer')}>For bedrifter <ArrowRight/></button></div><small><ShieldCheck/> Passordet sendes aldri til nettleserens localStorage.</small></div>
   <div className="hero-visual" aria-hidden="true"><div className="mail-preview"><div className="preview-top"><BrandLogo compact/><span><RefreshCw/> Oppdatert nå</span></div><div className="preview-body"><div className="preview-side"><i/><i/><i/><i/></div><div className="preview-list"><b>Innboks</b><span/><span/><span/></div><div className="preview-letter"><i>VEDØY</i><b>Alt arbeidet.<br/>Én rolig innboks.</b><span/><span/></div></div></div><div className="floating-card security"><ShieldCheck/><span><b>Trygg tilkobling</b><small>IMAP + SMTP</small></span></div><div className="floating-card speed"><Zap/><span><b>Alltid oppdatert</b><small>Smart bakgrunnssjekk</small></span></div></div>
  </section>
  <section className="benefit-strip"><span>BYGGED FOR FOKUS</span><div><b>01</b> Jobb og privat</div><div><b>02</b> Ekte IMAP/SMTP</div><div><b>03</b> KI-hjelp til svar</div><div><b>04</b> Kontroll på data</div></section>
  <section className="landing-features"><div className="section-heading"><span>DERFOR VEDØY MAILBOX</span><h2>E-post som arbeider<br/>slik du gjør.</h2></div><div className="feature-grid"><article><Briefcase/><h3>Skill jobb fra privat</h3><p>Koble til kontoene du trenger og behold en tydelig arbeidsflyt uten å miste oversikten.</p></article><article><RefreshCw/><h3>Fersk innboks</h3><p>Automatisk oppdatering når fanen er aktiv, med intervall du selv velger i innstillingene.</p></article><article><Sparkles/><h3>Svar med KI</h3><p>Lag et redigerbart utkast på sekunder. Du bestemmer alltid hva som faktisk sendes.</p></article></div></section>
  <section className="business-cta"><div><span>VEDØY FOR VIRKSOMHETER</span><h2>Skaff deg Vedøy Mailbox i dag.</h2><p>Gi bedriften en profesjonell e-postopplevelse fra første domene. Oppsettet tar bare noen minutter.</p></div><div className="business-actions"><button onClick={()=>onBusiness('customer')}>Bli bedriftskunde <ArrowRight/></button><button onClick={()=>onBusiness('login')}>Logg inn som bedrift</button></div></section>
 </main>
 <footer className="landing-foot"><BrandLogo compact/><span className="legal-links"><a href="/privacy">Personvern</a><a href="/terms">Vilkår</a><a href="/cookies">Cookies</a><a href="/accessibility">Tilgjengelighet</a></span><span>© 2026 VEDØY</span></footer>
 </div>}

function BusinessAccess({initialMode,configured,onClose,onLogin,onBecomeCustomer}){const[mode,setMode]=useState(initialMode),[form,setForm]=useState(()=>{try{return{company:'',orgNumber:'',email:'',...JSON.parse(localStorage.getItem('vedoy.business')||'{}')}}catch{return{company:'',orgNumber:'',email:''}}}),[busy,setBusy]=useState(false);const submit=e=>{e.preventDefault();setBusy(true);window.setTimeout(()=>{if(mode==='customer'){localStorage.setItem('vedoy.business',JSON.stringify(form));onBecomeCustomer()}else onLogin();setBusy(false)},350)};return <div className="modal-backdrop"><form className="business-modal" onSubmit={submit}><button type="button" className="icon close" onClick={onClose}><X/></button><BrandLogo/><div className="business-tabs"><button type="button" className={mode==='login'?'active':''} onClick={()=>setMode('login')}>Logg inn</button><button type="button" className={mode==='customer'?'active':''} onClick={()=>setMode('customer')}>Bli kunde</button></div>{mode==='login'?<><h2>Velkommen tilbake</h2><p>Fortsett til bedriftens tilkoblede innboks.</p><label>E-postadresse<input required type="email" value={form.email} onChange={e=>setForm(x=>({...x,email:e.target.value}))} placeholder="navn@bedrift.no"/></label><small className="business-hint">{configured?'Denne nettleseren har allerede et lagret e-postoppsett.':'Du blir bedt om å koble til bedriftens e-postkonto.'}</small></>:<><h2>Kom i gang med Mailbox</h2><p>Opprett bedriftsprofilen, og koble deretter til den første e-postkontoen.</p><label>Bedriftsnavn<input required value={form.company} onChange={e=>setForm(x=>({...x,company:e.target.value}))} placeholder="Bedrift AS"/></label><label>Organisasjonsnummer<input required inputMode="numeric" pattern="[0-9 ]{9,11}" value={form.orgNumber} onChange={e=>setForm(x=>({...x,orgNumber:e.target.value}))} placeholder="937 024 622"/></label><label>Ansvarlig e-post<input required type="email" value={form.email} onChange={e=>setForm(x=>({...x,email:e.target.value}))} placeholder="leder@bedrift.no"/></label><small className="business-hint">Den første profilen blir ansvarlig for bedriftens oppsett.</small></>}<button className="business-submit" disabled={busy}>{busy?<><Loader2/> Klargjør…</>:<>{mode==='login'?'Fortsett':'Opprett bedriftsprofil'} <ArrowRight/></>}</button></form></div>}

function Workspace({unread,onClose,onCompose}){const saved=()=>{try{return JSON.parse(localStorage.getItem('vedoy.modules'))||[{id:'inbox',name:'Inbox',kind:'inbox'},{id:'tasks',name:'Today',kind:'tasks'}]}catch{return[]}};const[modules,setModules]=useState(saved),[drag,setDrag]=useState(null),[addMenu,setAddMenu]=useState(false),[tasks,setTasks]=useState(['Confirm campaign selects','Review Copenhagen notes','Approve shipment']);useEffect(()=>localStorage.setItem('vedoy.modules',JSON.stringify(modules)),[modules]);const move=target=>{if(!drag||drag===target)return;const a=[...modules],from=a.findIndex(x=>x.id===drag),to=a.findIndex(x=>x.id===target);a.splice(to,0,a.splice(from,1)[0]);setModules(a)};const add=(kind,name)=>{if(!modules.some(x=>x.kind===kind))setModules(x=>[...x,{id:kind,name,kind}]);setAddMenu(false)};return <div className="workspace"><div className="workspace-bar"><div><span className="mark">V</span><div><h1>Vedøy workspace</h1><p>Drag modules to arrange your day.</p></div></div><div className="menu-wrap"><button className="add-module" onClick={()=>setAddMenu(x=>!x)}><Plus/> Add module</button>{addMenu&&<div className="popover add-pop"><button onClick={()=>add('notes','Notes')}>Notes</button><button onClick={()=>add('campaigns','Campaigns')}>Campaigns</button><button onClick={()=>add('tasks','Today')}>Tasks</button><button onClick={()=>add('inbox','Inbox')}>Inbox</button></div>}<button className="icon" onClick={onClose}><X/></button></div></div><div className="module-grid">{modules.length?modules.map(m=><section draggable key={m.id} onDragStart={()=>setDrag(m.id)} onDragOver={e=>e.preventDefault()} onDrop={()=>move(m.id)} className="module"><div className="module-head"><span>⋮⋮</span><b>{m.name}</b><button onClick={()=>setModules(x=>x.filter(y=>y.id!==m.id))}><X/></button></div>{m.kind==='inbox'&&<div className="mod-content"><div className="metric">{unread} <small>unread</small></div><button onClick={onCompose}>Compose email <ArrowLeft/></button></div>}{m.kind==='tasks'&&<div className="mod-content">{tasks.map((t,i)=><p key={t}><button className="task-check" onClick={()=>setTasks(x=>x.filter((_,n)=>n!==i))}><Check/></button>{t}</p>)}</div>}{m.kind==='notes'&&<div className="mod-content"><textarea defaultValue={localStorage.getItem('vedoy.notes')||''} onBlur={e=>localStorage.setItem('vedoy.notes',e.target.value)} placeholder="A quiet space for working notes…"/></div>}{m.kind==='campaigns'&&<div className="mod-content"><div className="metric">0 <small>active campaigns</small></div><button onClick={()=>add('notes','Campaign brief')}>Create campaign brief <Plus/></button></div>}</section>):<div className="empty-modules"><p>Your workspace is empty.</p><button onClick={()=>setAddMenu(true)}>Add a module</button></div>}</div></div>}

function SettingsModal({prefs,setPrefs,live,onClose,onReconnect,onForget}){const[draft,setDraft]=useState(prefs),[tab,setTab]=useState('General'),[newLabel,setNewLabel]=useState('');const save=()=>{setPrefs(draft);onClose()};return <div className="modal-backdrop"><div className="settings-modal"><div className="settings-head"><div><h2>Settings</h2><p>Personalize Vedøy Mail.</p></div><button className="icon" onClick={onClose}><X/></button></div><div className="settings-body"><nav>{['General','Compose','Labels','Account'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x}</button>)}</nav><section>{tab==='General'&&<><h3>Appearance</h3><label>Theme<select value={draft.theme} onChange={e=>setDraft(x=>({...x,theme:e.target.value}))}><option value="light">Light</option><option value="dark">Dark</option><option value="system">Use system</option></select></label><label>Message density<select value={draft.density} onChange={e=>setDraft(x=>({...x,density:e.target.value}))}><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><label className="switch-row"><span><b>Desktop notifications</b><small>Show a notification for new mail.</small></span><input type="checkbox" checked={draft.notifications} onChange={e=>setDraft(x=>({...x,notifications:e.target.checked}))}/></label></>}{tab==='Compose'&&<><h3>Compose</h3><label>Default signature<textarea value={draft.signature} onChange={e=>setDraft(x=>({...x,signature:e.target.value}))} placeholder="Your signature"/></label><p className="setting-note">This signature is appended to every outgoing message.</p></>}{tab==='Labels'&&<><h3>Labels</h3><div className="settings-labels">{draft.labels.map((x,i)=><span key={x}><i style={{background:palette[i%palette.length]}}/>{x}<button onClick={()=>setDraft(y=>({...y,labels:y.labels.filter(z=>z!==x)}))}><X/></button></span>)}</div><div className="new-label"><input value={newLabel} onChange={e=>setNewLabel(e.target.value)} placeholder="New label"/><button disabled={!newLabel.trim()} onClick={()=>{setDraft(x=>({...x,labels:[...new Set([...x.labels,newLabel.trim()])]}));setNewLabel('')}}>Add</button></div></>}{tab==='Account'&&<><h3>Mailbox</h3><div className="account-status"><span className={live?'online':''}/><div><b>{live?'Connected':'Disconnected'}</b><small>IMAP and SMTP mailbox connection</small></div></div><button className="setting-action" onClick={onReconnect}>Reconnect or change mailbox</button><button className="setting-action danger" onClick={()=>window.confirm('Forget the saved mailbox on this server?')&&onForget()}>Forget saved mailbox</button></>}</section></div><div className="settings-foot"><button onClick={onClose}>Cancel</button><button className="save" onClick={save}>Save changes</button></div></div></div>}

function SettingsModalV2({prefs,setPrefs,live,accounts,activeAccountId,onSwitch,onRemove,onClose,onReconnect,onForget}){const[draft,setDraft]=useState(prefs),[tab,setTab]=useState('Generelt'),[newLabel,setNewLabel]=useState('');const save=()=>{setPrefs({...draft,refreshSeconds:Number(draft.refreshSeconds)});onClose()};return <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} className="modal-backdrop"><motion.div initial={{opacity:0,y:18,scale:.985}} animate={{opacity:1,y:0,scale:1}} className="settings-modal"><div className="settings-head"><div><h2>Innstillinger</h2><p>Tilpass Vedøy Mailbox.</p></div><button className="icon" aria-label="Lukk" onClick={onClose}><X/></button></div><div className="settings-body"><nav>{['Generelt','Visning','Skrive','Etiketter','Konto'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x}</button>)}</nav><section>{tab==='Generelt'&&<><h3>Utseende og oppdatering</h3><label>Tema<select value={draft.theme} onChange={e=>setDraft(x=>({...x,theme:e.target.value}))}><option value="light">Lyst</option><option value="dark">Mørkt</option><option value="system">Følg enheten</option></select></label><label>Meldingstetthet<select value={draft.density} onChange={e=>setDraft(x=>({...x,density:e.target.value}))}><option value="comfortable">Komfortabel</option><option value="compact">Kompakt</option></select></label><label className="refresh-setting"><span><b>Se etter ny e-post</b><small>Kun når fanen er aktiv og nettet er tilgjengelig.</small></span><select value={draft.refreshSeconds} onChange={e=>setDraft(x=>({...x,refreshSeconds:Number(e.target.value)}))}><option value="15">Hvert 15. sekund</option><option value="30">Hvert 30. sekund</option><option value="60">Hvert minutt</option><option value="300">Hvert 5. minutt</option></select></label><p className="setting-note">30 sekunder er anbefalt. Det gir fersk innboks uten unødvendige IMAP-kall.</p><label className="switch-row"><span><b>Skrivebordsvarsler</b><small>Vis et varsel når ny e-post kommer.</small></span><input type="checkbox" checked={draft.notifications} onChange={e=>setDraft(x=>({...x,notifications:e.target.checked}))}/></label></>}{tab==='Visning'&&<><h3>Visning av meldinger</h3><label className="switch-row"><span><b>Vis HTML</b><small>Bevar formatering, knapper og oppsett i e-posten.</small></span><input type="checkbox" checked={draft.displayHtml} onChange={e=>setDraft(x=>({...x,displayHtml:e.target.checked}))}/></label><label className="switch-row"><span><b>Vis vedlagte bilder</b><small>Forhåndsvis bildevedlegg under meldingen.</small></span><input type="checkbox" checked={draft.showAttachedImages} onChange={e=>setDraft(x=>({...x,showAttachedImages:e.target.checked}))}/></label><label className="switch-row"><span><b>Last eksterne bilder</b><small>Av som standard for å hindre sporingspiksler.</small></span><input type="checkbox" checked={draft.loadRemoteImages} onChange={e=>setDraft(x=>({...x,loadRemoteImages:e.target.checked}))}/></label><label className="switch-row"><span><b>Marker som lest ved åpning</b><small>Kan slås av hvis du vil markere meldinger manuelt.</small></span><input type="checkbox" checked={draft.markReadOnOpen} onChange={e=>setDraft(x=>({...x,markReadOnOpen:e.target.checked}))}/></label></>}{tab==='Skrive'&&<><h3>Ny e-post</h3><label>Standardsignatur<textarea value={draft.signature} onChange={e=>setDraft(x=>({...x,signature:e.target.value}))} placeholder="Din signatur"/></label><p className="setting-note">Signaturen legges til utgående e-post. Utkast lagres automatisk i denne nettleseren.</p><div className="shortcut-card"><b>Raskere med tastaturet</b><span><kbd>C</kbd> ny e-post · <kbd>R</kbd> svar · <kbd>U</kbd> lest/ulest · <kbd>J/K</kbd> naviger · <kbd>/</kbd> søk</span></div></>}{tab==='Etiketter'&&<><h3>Etiketter</h3><div className="settings-labels">{draft.labels.map((x,i)=><span key={x}><i style={{background:palette[i%palette.length]}}/>{x}<button onClick={()=>setDraft(y=>({...y,labels:y.labels.filter(z=>z!==x)}))}><X/></button></span>)}</div><div className="new-label"><input value={newLabel} onChange={e=>setNewLabel(e.target.value)} placeholder="Ny etikett"/><button disabled={!newLabel.trim()} onClick={()=>{setDraft(x=>({...x,labels:[...new Set([...x.labels,newLabel.trim()])]}));setNewLabel('')}}>Legg til</button></div></>}{tab==='Konto'&&<><div className="account-settings-title"><div><h3>E-postkontoer</h3><p>Skill jobb og privat, og bytt uten å logge ut.</p></div><button className="setting-add-account" onClick={onReconnect}><Plus/> Legg til konto</button></div><div className="settings-accounts">{accounts.map(account=><div key={account.id} className={account.id===activeAccountId?'active':''}><span className="account-dot">{account.label?.slice(0,2).toUpperCase()}</span><div><b>{account.label}</b><small>{account.email}</small></div>{account.id===activeAccountId?<span className="active-account"><CheckCircle2/> Aktiv</span>:<button onClick={()=>onSwitch(account.id)}>Bruk</button>}<button className="remove-account" aria-label={`Fjern ${account.email}`} onClick={()=>window.confirm(`Vil du fjerne ${account.email} fra Vedøy Mailbox?`)&&onRemove(account.id)}><Trash2/></button></div>)}</div>{!accounts.length?<div className="account-status"><span/><div><b>Ingen konto tilkoblet</b><small>Legg til en IMAP- og SMTP-konto.</small></div></div>:null}<button className="setting-action danger" onClick={()=>window.confirm('Vil du glemme alle lagrede e-postkontoer?')&&onForget()}>Glem alle e-postkontoer</button></>}</section></div><div className="settings-foot"><button onClick={onClose}>Avbryt</button><button className="save" onClick={save}>Lagre lokalt</button></div></motion.div></motion.div>}

const mailProviders={
 domeneshop:{label:'Domeneshop',imapHost:'imap.domeneshop.no',imapPort:993,smtpHost:'smtp.domeneshop.no',smtpPort:465,detail:'Standardoppsett for e-post som håndteres av Domeneshop.'},
 custom:{label:'Annen',imapHost:'',imapPort:993,smtpHost:'',smtpPort:465,detail:'Bruk innstillingene fra e-postleverandøren din.'}
};

function Connect({onClose,onConnected}){
 const[provider,setProvider]=useState('domeneshop'),[form,setForm]=useState({email:'',password:'',...mailProviders.domeneshop}),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const change=(k,v)=>setForm(x=>({...x,[k]:v}));
 const chooseProvider=id=>{const next=mailProviders[id];setProvider(id);setError('');setForm(x=>({...x,imapHost:next.imapHost,imapPort:next.imapPort,smtpHost:next.smtpHost,smtpPort:next.smtpPort}))};
 const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form,provider})});const data=await r.json().catch(()=>({}));if(!r.ok)return setError(data.error||'Kunne ikke koble til kontoen.');onConnected(data)}finally{setBusy(false)}};
 const selected=mailProviders[provider];
 return <motion.div initial={{opacity:0}} animate={{opacity:1}} className="modal-backdrop"><motion.form initial={{opacity:0,y:20,scale:.98}} animate={{opacity:1,y:0,scale:1}} transition={{type:'spring',stiffness:360,damping:30}} className="connect-modal provider-connect" onSubmit={submit}><button type="button" className="icon close" onClick={onClose}><X/></button><BrandLogo compact/><span className="modal-kicker">FLERE KONTOER · ÉN RO</span><h2>Legg til e-postkonto</h2><p>Velg leverandør. Servernavn og porter er offentlige leverandørinnstillinger; kontoen og innloggingen lagres separat og kryptert for denne nettleseren.</p><fieldset className="provider-fieldset"><legend>Velg e-postleverandør</legend><div className="provider-grid">{Object.entries(mailProviders).map(([id,item])=><button type="button" key={id} className={provider===id?'active':''} aria-pressed={provider===id} onClick={()=>chooseProvider(id)}><b>{item.label}</b><span>{id==='outlook'?'OAuth2 kreves':id==='gmail'?'App-passord':'IMAP + SMTP'}</span></button>)}</div></fieldset><div className={`provider-note ${provider==='outlook'?'warning':''}`}><span>{selected.detail}</span>{provider==='gmail'?<a href="https://support.google.com/accounts/answer/185833" target="_blank" rel="noreferrer">Slik lager du app-passord</a>:provider==='outlook'?<a href="https://support.microsoft.com/office/pop-imap-and-smtp-settings-for-outlook-com-d088b986-291d-42b8-9564-9c414e2aa040" target="_blank" rel="noreferrer">Se Microsofts krav</a>:null}</div>{provider!=='outlook'?<><label>E-postadresse<input required type="email" autoComplete="username" value={form.email} onChange={e=>change('email',e.target.value)} placeholder={provider==='gmail'?'navn@gmail.com':'navn@bedrift.no'}/></label><label>{provider==='gmail'?'Google app-passord':'Passord til e-post'}<input required type="password" autoComplete="current-password" value={form.password} onChange={e=>change('password',e.target.value)} placeholder={provider==='gmail'?'16-tegns app-passord':'Passord eller app-passord'}/></label>{provider==='custom'?<div className="two"><label>IMAP-vert<input required value={form.imapHost} onChange={e=>change('imapHost',e.target.value)}/></label><label>IMAP-port<input required type="number" value={form.imapPort} onChange={e=>change('imapPort',e.target.value)}/></label><label>SMTP-vert<input required value={form.smtpHost} onChange={e=>change('smtpHost',e.target.value)}/></label><label>SMTP-port<input required type="number" value={form.smtpPort} onChange={e=>change('smtpPort',e.target.value)}/></label></div>:<div className="provider-servers"><span>IMAP <b>{form.imapHost}:{form.imapPort}</b></span><span>SMTP <b>{form.smtpHost}:{form.smtpPort}</b></span></div>}<small className="hint"><ShieldCheck/> Passordet legges aldri i localStorage og deles ikke med andre brukere.</small></>:<div className="oauth-required"><b>Outlook kan kobles til, men bare med OAuth2.</b><p>Microsoft har fjernet vanlig passordinnlogging for IMAP. En sikker «Fortsett med Microsoft»-flyt må konfigureres før Outlook-kontoer kan legges til.</p></div>}{error&&<small className="error">{error}</small>}{provider!=='outlook'?<button className="connect-submit" disabled={busy}>{busy?<><Loader2/> Tester IMAP sikkert…</>:<>Legg til konto <Plus/></>}</button>:null}</motion.form></motion.div>
}

function AiReply({message,onClose,onDraft}){
 const[tone,setTone]=useState('Profesjonell og varm'),[notes,setNotes]=useState(''),[apiKey,setApiKey]=useState(''),[configured,setConfigured]=useState(false),[checking,setChecking]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState('');
 useEffect(()=>{fetch('/api/ai/status').then(r=>r.json()).then(x=>setConfigured(!!x.configured)).catch(()=>{}).finally(()=>setChecking(false))},[]);
 const generate=async()=>{setBusy(true);setError('');try{if(!configured){if(!apiKey.trim())throw Error('Legg inn en OpenAI API-nøkkel først.');const setup=await fetch('/api/ai/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey})});if(!setup.ok){const x=await setup.json();throw Error(x.error||'Kunne ikke lagre API-nøkkelen.')}setConfigured(true)}const response=await fetch('/api/ai/reply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sender:`${message.from} <${message.email}>`,subject:message.subject,message:message.body||message.preview,tone,notes})});const result=await response.json();if(!response.ok)throw Error(result.error||'Kunne ikke lage et svarutkast.');onDraft(result.draft)}catch(e){setError(e.message)}finally{setBusy(false)}};
 return <div className="modal-backdrop"><div className="ai-modal"><div className="ai-head"><span><Sparkles/></span><div><h2>Hjelp meg å svare</h2><p>KI lager et utkast du kan redigere før sending.</p></div><button className="icon" aria-label="Lukk" onClick={onClose}><X/></button></div><div className="ai-context"><small>SVARER PÅ</small><b>{message.subject}</b><span>{message.from}</span></div>{!checking&&!configured&&<label className="ai-key">OpenAI API-nøkkel<input type="password" autoComplete="off" value={apiKey} onChange={e=>setApiKey(e.target.value)} placeholder="sk-…"/><small>Lagres kryptert på Vedøy-serveren.</small></label>}<label>Tone<select value={tone} onChange={e=>setTone(e.target.value)}><option>Profesjonell og varm</option><option>Kort og direkte</option><option>Vennlig og uformell</option><option>Detaljert og hjelpsom</option></select></label><label>Hva bør svaret inneholde? <span>Valgfritt</span><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="For eksempel: Bekreft møtet på tirsdag, men ikke lov en leveringstid."/></label>{error&&<small className="error">{error}</small>}<p className="ai-privacy">E-postinnholdet sendes til OpenAI først når du trykker «Lag utkast». Ingenting sendes til mottakeren automatisk.</p><div className="ai-actions"><button onClick={onClose}>Avbryt</button><button className="generate" disabled={busy||checking} onClick={generate}><Sparkles/>{busy?'Lager utkast…':'Lag utkast'}</button></div></div></div>;
}

const attachmentUrl=(message,folder,attachment,download=false)=>`/api/messages/${encodeURIComponent(message.id)}/attachments/${attachment.id}?folder=${encodeURIComponent(folder)}${download?'&download=1':''}`;
const formatBytes=size=>{const value=Number(size||0);if(value<1024)return `${value} B`;if(value<1024*1024)return `${(value/1024).toFixed(value<10240?1:0)} kB`;return `${(value/1024/1024).toFixed(1)} MB`};
function MessageContent({message,folder,prefs,loading,error,onRetry}){
 if(loading)return <div className="message-state" role="status"><Loader2/><b>Åpner meldingen</b><span>Henter innhold og vedlegg sikkert…</span></div>;
 if(error)return <div className="message-state error-state"><Mail/><b>Meldingen kunne ikke åpnes</b><span>{error}</span><button onClick={onRetry}><RefreshCw/> Prøv igjen</button></div>;
 const attachments=message.attachments||[],body=String(message.body||message.preview||'').trim();
 return <div className="message-content" key={`${message.id}-${attachments.length}`}>
  {prefs.displayHtml&&message.html?<><EmailHtml html={message.html} message={message} folder={folder} attachments={attachments} allowRemoteImages={prefs.loadRemoteImages}/>{!prefs.loadRemoteImages&&<div className="privacy-note"><ShieldCheck/><span><b>Eksterne bilder er blokkert</b><small>Innebygde bilder og vedlegg vises fortsatt. Du kan endre dette under Innstillinger → Visning.</small></span></div>}</>:body?<div className="body">{body.split('\n').map((p,i)=><p key={i}>{p||' '}</p>)}</div>:attachments.length?<div className="attachment-only"><ImageIcon/><div><b>Denne meldingen består av vedlegg</b><span>Det finnes ingen egen meldingstekst, men alle filene vises nedenfor.</span></div></div>:<div className="attachment-only"><Mail/><div><b>Ingen synlig meldingstekst</b><span>Avsenderen sendte en tom melding.</span></div></div>}
  <AttachmentPanel message={message} folder={folder} attachments={attachments} showImages={prefs.showAttachedImages}/>
 </div>;
}
function AttachmentPreview({message,folder,attachment}){const[loaded,setLoaded]=useState(false),[failed,setFailed]=useState(false);return <div className={`attachment-preview ${loaded?'loaded':''}`}>{!failed?<img src={attachmentUrl(message,folder,attachment)} alt={attachment.name} loading="lazy" onLoad={()=>setLoaded(true)} onError={()=>setFailed(true)}/>:<div className="preview-failed"><ImageIcon/><span>Forhåndsvisning utilgjengelig</span></div>}{!loaded&&!failed&&<div className="image-skeleton"><Loader2/></div>}</div>}
function AttachmentPanel({message,folder,attachments,showImages}){const[downloading,setDownloading]=useState(false),[error,setError]=useState('');if(!attachments.length)return null;const images=attachments.filter(x=>x.isImage);const save=async attachment=>{const response=await fetch(attachmentUrl(message,folder,attachment,true));if(!response.ok)throw Error('Kunne ikke laste ned vedlegget.');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=attachment.name;document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1500)};const downloadAll=async()=>{setDownloading(true);setError('');try{for(const attachment of attachments)await save(attachment)}catch(e){setError(e.message)}finally{setDownloading(false)}};return <section className="attachments" aria-label="Vedlegg"><div className="attachments-head"><div><Paperclip/><span><b>{attachments.length} {attachments.length===1?'vedlegg':'vedlegg'}</b><small>{formatBytes(attachments.reduce((sum,item)=>sum+item.size,0))} totalt</small></span></div>{attachments.length>1&&<button onClick={downloadAll} disabled={downloading}>{downloading?<Loader2/>:<Download/>}{downloading?'Laster ned…':'Last ned alle'}</button>}</div>{showImages&&images.length>0&&<div className="attachment-gallery">{images.map(attachment=><article key={attachment.id}><AttachmentPreview message={message} folder={folder} attachment={attachment}/><div><span title={attachment.name}>{attachment.name}</span><small>{formatBytes(attachment.size)}</small></div><div className="attachment-actions"><a href={attachmentUrl(message,folder,attachment)} target="_blank" rel="noreferrer" aria-label={`Åpne ${attachment.name}`}><Eye/></a><a href={attachmentUrl(message,folder,attachment,true)} download={attachment.name} aria-label={`Last ned ${attachment.name}`}><Download/></a></div></article>)}</div>}<div className="attachment-list">{attachments.filter(x=>!showImages||!x.isImage).map(attachment=><div key={attachment.id}><span className="file-icon">{attachment.isImage?<ImageIcon/>:<File/>}</span><span><b>{attachment.name}</b><small>{attachment.contentType} · {formatBytes(attachment.size)}</small></span><a href={attachmentUrl(message,folder,attachment,true)} download={attachment.name}><Download/> Last ned</a></div>)}</div>{error&&<small className="attachment-error">{error}</small>}</section>}
function EmailHtml({html,message,folder,attachments,allowRemoteImages}){
 const frame=useRef(null),[height,setHeight]=useState(240);
 const documentHtml=useMemo(()=>{let content=html;for(const attachment of attachments){if(!attachment.contentId)continue;const url=attachmentUrl(message,folder,attachment);for(const cid of [`cid:${attachment.contentId}`,`cid:${encodeURIComponent(attachment.contentId)}`])content=content.split(cid).join(url)}const remote=allowRemoteImages?" http: https:":'';const head=`<meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self' data: blob:${remote}; style-src 'unsafe-inline'${remote}; font-src data:${remote}; script-src 'none'; object-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'none'"><style>html,body{margin:0;padding:0;background:transparent;color:#3f433d;font:14px/1.55 Arial,sans-serif;overflow:hidden;overflow-wrap:anywhere}img{max-width:100%;height:auto}table{max-width:100%!important}pre{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#405a70}</style>`;return /<head[\s>]/i.test(content)?content.replace(/<head([^>]*)>/i,`<head$1>${head}`):`<!doctype html><html><head>${head}</head><body>${content}</body></html>`},[html,message.id,folder,attachments,allowRemoteImages]);
 useEffect(()=>setHeight(240),[documentHtml]);
 const fit=()=>{try{const doc=frame.current?.contentDocument;if(!doc)return;const resize=()=>setHeight(Math.min(20000,Math.max(120,doc.documentElement.scrollHeight,doc.body?.scrollHeight||0)));resize();doc.querySelectorAll('img').forEach(img=>img.addEventListener('load',resize,{once:true}));window.setTimeout(resize,250)}catch{setHeight(600)}};
 return <iframe ref={frame} className="email-html" title="E-postinnhold" sandbox="allow-same-origin allow-popups" referrerPolicy="no-referrer" srcDoc={documentHtml} style={{height}} onLoad={fit}/>;
}

const dateValue=d=>{const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)};
const sameDay=(a,b)=>dateValue(a)===dateValue(b);
function CalendarView({seed,onClose}){
 const now=new Date(),today=dateValue(now),[view,setView]=useState('week'),[focus,setFocus]=useState(today),[events,setEvents]=useState(()=>{try{return JSON.parse(localStorage.getItem('vedoy.calendar.events')||'[]')}catch{return[]}}),[editing,setEditing]=useState(seed?{id:'',title:seed.title||'',guests:seed.guests||'',location:'',link:'',start:`${today}T09:00`,end:`${today}T09:30`,repeat:'none',reminder:'15'}:null);
 useEffect(()=>localStorage.setItem('vedoy.calendar.events',JSON.stringify(events)),[events]);
 const focusDate=new Date(`${focus}T12:00`),monthStart=new Date(focusDate.getFullYear(),focusDate.getMonth(),1),startOffset=(monthStart.getDay()+6)%7,monthDays=Array.from({length:42},(_,i)=>new Date(monthStart.getFullYear(),monthStart.getMonth(),i-startOffset+1));
 const occursOn=(event,day)=>{const start=new Date(event.start),target=dateValue(day);if(sameDay(start,day))return true;if(event.repeat==='weekly')return day>=start&&day.getDay()===start.getDay();if(event.repeat==='monthly')return day>=start&&day.getDate()===start.getDate();return false};
 const visibleEvents=events.filter(event=>occursOn(event,focusDate)).sort((a,b)=>a.start.localeCompare(b.start));
 const save=e=>{e.preventDefault();if(!editing.title.trim())return;const next={...editing,id:editing.id||crypto.randomUUID()};setEvents(items=>editing.id?items.map(item=>item.id===next.id?next:item):[...items,next]);setEditing(null)};
 const changeFocus=amount=>{const d=new Date(`${focus}T12:00`);if(view==='month')d.setMonth(d.getMonth()+amount);else d.setDate(d.getDate()+amount*(view==='week'?7:1));setFocus(dateValue(d))};
 const availability=['09:00','10:30','13:00','14:30','15:30'].filter(time=>!events.some(event=>sameDay(event.start,focusDate)&&event.start.slice(11,16)===time));
 return <div className="calendar-page"><header className="calendar-head"><div><span>VEDØY GROWTH · LOKAL KALENDER</span><h1>Kalender</h1></div><div className="calendar-actions"><button onClick={()=>changeFocus(-1)}><ChevronLeft/></button><button onClick={()=>setFocus(today)}>I dag</button><button onClick={()=>changeFocus(1)}><ChevronRight/></button><div className="calendar-tabs">{['day','week','month'].map(item=><button key={item} className={view===item?'active':''} onClick={()=>setView(item)}>{item==='day'?'Dag':item==='week'?'Uke':'Måned'}</button>)}</div><button className="calendar-new" onClick={()=>setEditing({id:'',title:'',guests:'',location:'',link:'',start:`${focus}T09:00`,end:`${focus}T09:30`,repeat:'none',reminder:'15'})}><Plus/> Ny avtale</button><button className="icon" onClick={onClose}><X/></button></div></header><main className="calendar-main"><section className="calendar-board"><div className="calendar-title"><h2>{focusDate.toLocaleDateString('nb-NO',{weekday:view==='day'?'long':undefined,month:'long',year:'numeric',day:view==='day'?'numeric':undefined})}</h2><span>{visibleEvents.length} avtaler denne dagen</span></div>{view==='month'?<div className="month-grid">{['Man','Tir','Ons','Tor','Fre','Lør','Søn'].map(d=><b key={d}>{d}</b>)}{monthDays.map(day=>{const count=events.filter(event=>occursOn(event,day)).length;return <button key={day.toISOString()} className={`${sameDay(day,new Date())?'today':''} ${day.getMonth()===focusDate.getMonth()?'':'muted'}`} onClick={()=>{setFocus(dateValue(day));setView('day')}}><span>{day.getDate()}</span>{count?<i>{count} avtale{count>1?'r':''}</i>:null}</button>})}</div>:<div className={`agenda ${view}`}>{(view==='week'?Array.from({length:7},(_,i)=>{const d=new Date(focusDate);d.setDate(d.getDate()-((d.getDay()+6)%7)+i);return d}):[focusDate]).map(day=><article key={dateValue(day)}><h3>{day.toLocaleDateString('nb-NO',{weekday:'short',day:'numeric',month:'short'})}</h3>{events.filter(event=>occursOn(event,day)).sort((a,b)=>a.start.localeCompare(b.start)).map(event=><button key={event.id} className="calendar-event" onClick={()=>setEditing(event)}><time>{event.start.slice(11,16)}</time><span><b>{event.title}</b><small>{event.guests||event.location||'Ingen gjester'}</small></span>{event.link?<Video/>:null}</button>)}{!events.some(event=>occursOn(event,day))&&<button className="calendar-empty" onClick={()=>{setFocus(dateValue(day));setEditing({id:'',title:'',guests:'',location:'',link:'',start:`${dateValue(day)}T09:00`,end:`${dateValue(day)}T09:30`,repeat:'none',reminder:'15'})}}>+ Ledig tid</button>}</article>)}</div>}</section><aside className="calendar-side"><h3>Tilgjengelighet</h3><p>Lokalt beregnet fra avtalene dine.</p><div className="suggestions">{availability.map(time=><button key={time} onClick={()=>setEditing({id:'',title:'',guests:'',location:'',link:'',start:`${focus}T${time}`,end:`${focus}T${String(Number(time.slice(0,2))+1).padStart(2,'0')}:00`,repeat:'none',reminder:'15'})}>{time} · ledig</button>)}</div><hr/><h3>Fase 1</h3><p>Avtaler lagres lokalt i denne nettleseren. Google/Microsoft-synk og teamdeling krever sikker backend i fase 2.</p></aside></main>{editing&&<div className="modal-backdrop"><form className="event-modal" onSubmit={save}><button type="button" className="icon close" onClick={()=>setEditing(null)}><X/></button><span className="modal-kicker">AVTALE</span><h2>{editing.id?'Rediger avtale':'Ny avtale'}</h2><label>Tittel<input required value={editing.title} onChange={e=>setEditing(x=>({...x,title:e.target.value}))} placeholder="Hva skal dere gjøre?"/></label><label>Gjester <input value={editing.guests} onChange={e=>setEditing(x=>({...x,guests:e.target.value}))} placeholder="navn@bedrift.no, flere@…"/></label><div className="two"><label>Start<input required type="datetime-local" value={editing.start} onChange={e=>setEditing(x=>({...x,start:e.target.value}))}/></label><label>Slutt<input required type="datetime-local" value={editing.end} onChange={e=>setEditing(x=>({...x,end:e.target.value}))}/></label></div><label>Sted<input value={editing.location} onChange={e=>setEditing(x=>({...x,location:e.target.value}))} placeholder="Kontor, Teams eller adresse"/></label><label>Videolenke<input type="url" value={editing.link} onChange={e=>setEditing(x=>({...x,link:e.target.value}))} placeholder="https://…"/></label><div className="two"><label>Gjenta<select value={editing.repeat} onChange={e=>setEditing(x=>({...x,repeat:e.target.value}))}><option value="none">Ingen</option><option value="weekly">Ukentlig</option><option value="monthly">Månedlig</option></select></label><label>Påminnelse<select value={editing.reminder} onChange={e=>setEditing(x=>({...x,reminder:e.target.value}))}><option value="0">Ingen</option><option value="15">15 minutter før</option><option value="60">1 time før</option><option value="1440">1 dag før</option></select></label></div><div className="event-actions">{editing.id&&<button type="button" className="danger" onClick={()=>{setEvents(items=>items.filter(item=>item.id!==editing.id));setEditing(null)}}><Trash2/> Slett</button>}<span/><button type="button" onClick={()=>setEditing(null)}>Avbryt</button><button className="save" type="submit">Lagre avtale</button></div></form></div>}</div>
}

function LegalPage({type}){
 const pages={
  privacy:{title:'Personvern',kicker:'PERSONVERNERKLÆRING',sections:[['Behandlingsansvarlig','Vedøy Mailbox drives av Vedøy. Fyll inn korrekt juridisk virksomhetsnavn, organisasjonsnummer og kontaktadresse før publisering. Personvernspørsmål sendes til: [sett inn personvern-e-post].'],['Hva vi behandler','Når du kobler til en konto, behandler tjenesten e-postadresse, IMAP/SMTP-tilkobling, meldingsinnhold, vedlegg og tekniske sesjonsdata for å vise og sende e-post på din instruks. Passord lagres ikke i nettleserens localStorage; tilkoblingen håndteres server-side i beskyttede cookies.'],['Formål og grunnlag','Formålet er å levere e-posttjenesten, sikre innlogging og håndtere support. Behandlingsgrunnlag må avklares for den konkrete tjenestemodellen, normalt avtale, rettslig plikt eller berettiget interesse.'],['Lagring og sletting','Sesjoner og tilkoblingsdata slettes når du logger ut, glemmer kontoene eller når lagringstiden utløper. E-post ligger hos din e-postleverandør. Be om innsyn, retting eller sletting via kontaktadressen over.'],['Databehandlere og overføring','Hosting leveres av Vercel. E-post leveres av valgt e-postleverandør. KI-funksjoner skal bare brukes når du ber om et utkast; avklar leverandør, formål og overføring før funksjonen tilbys kommersielt.'],['Dine rettigheter','Du kan ha rett til innsyn, retting, sletting, begrensning, dataportabilitet og protest. Du kan klage til Datatilsynet.'] ]},
  terms:{title:'Bruksvilkår',kicker:'VILKÅR FOR VEDØY MAILBOX',sections:[['Tjenesten','Vedøy Mailbox er et verktøy for å koble til og administrere e-postkontoer via standard IMAP og SMTP. Du er ansvarlig for at du har rett til å koble til kontoen og innholdet du behandler.'],['Sikker bruk','Ikke del passord, app-passord eller sesjoner. Du må følge vilkårene til din e-postleverandør. Vedøy sender ikke e-post automatisk uten at du aktivt ber om det.'],['Tilgjengelighet og endringer','Tjenesten kan være midlertidig utilgjengelig, og funksjoner kan endres. Ikke bruk tjenesten som eneste arkiv eller som grunnlag for kritiske nødprosesser.'],['Kontakt','Juridisk virksomhetsnavn, organisasjonsnummer, adresse og kontaktinformasjon skal fylles inn her før kommersiell lansering.'] ]},
  cookies:{title:'Informasjonskapsler',kicker:'COOKIES OG LOKAL LAGRING',sections:[['Nødvendige cookies','Vedøy Mailbox bruker nødvendige HttpOnly-sesjonscookies for innlogging og sikker konto-/sesjonshåndtering. Disse er nødvendige for at tjenesten skal fungere.'],['Lokale valg','Nettleseren kan lagre ufølsomme preferanser, som tema, tetthet, utkast og lokale arbeidsnotater. Disse kan slettes i Innstillinger eller ved å rydde nettleserdata.'],['Analyse og markedsføring','Det er ikke lagt inn analyse- eller markedsføringscookies i denne versjonen. Hvis dette endres, må samtykkeløsning og cookie-erklæring oppdateres før sporing aktiveres.'] ]},
  accessibility:{title:'Tilgjengelighet',kicker:'ERKLÆRING OM TILGJENGELIGHET',sections:[['Mål','Vi arbeider for at Vedøy Mailbox skal kunne brukes på mobil, tablet og desktop, med tastatur, tydelige kontraster, lesbare størrelser og støtte for redusert bevegelse.'],['Kjente begrensninger','E-postinnhold fra andre avsendere kan ha dårlig tilgjengelighet. Enkelte komplekse HTML-meldinger, vedlegg og tredjepartsinnhold kan derfor ikke gjøres fullt tilgjengelig av tjenesten.'],['Tilbakemelding','Meld fra om barrierer til [sett inn support-e-post], og inkluder side, enhet og hva som ikke fungerer. Oppgi ikke passord eller e-postinnhold i meldingen.'] ]}
 };
 const page=pages[type]||pages.privacy;
 return <div className="legal-page"><header className="info-header"><BrandLogo/><button className="info-close" onClick={()=>{window.history.pushState({},'', '/');window.dispatchEvent(new PopStateEvent('popstate'))}}><ArrowLeft/> Tilbake</button></header><main className="legal-main"><span>{page.kicker}</span><h1>{page.title}</h1><p className="legal-intro">Sist oppdatert: 31. august 2026. Denne teksten må tilpasses virksomhetens faktiske oppsett og kontaktinformasjon.</p>{page.sections.map(([heading,text])=><section key={heading}><h2>{heading}</h2><p>{text}</p></section>)}</main></div>
}

const root=globalThis.__vedoyRoot||(globalThis.__vedoyRoot=createRoot(document.getElementById('root')));
const renderRoute=()=>{const type=window.location.pathname.slice(1);if(type==='om')return root.render(<InfoPage onClose={()=>{window.history.pushState({},'', '/');window.dispatchEvent(new PopStateEvent('popstate'))}}/>);root.render(['privacy','terms','cookies','accessibility'].includes(type)?<LegalPage type={type}/>:<><App/><LegalDock/></>)};
window.addEventListener('popstate',renderRoute);renderRoute();
